describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    linearWebhookSecret: 'secret',
    linearApiKey: 'linear-key',
    discordBotToken: 'discord-token',
    discordChannelId: '123456789',
  };

  it('throws on missing required field data.id', async () => {
    const payload = { ...SOURCE_EXAMPLE, data: { ...SOURCE_EXAMPLE.data, id: undefined } } as unknown as LinearWebhookPayload;
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: data.id');
  });

  it('throws on unsupported action', async () => {
    const payload = { ...SOURCE_EXAMPLE, action: 'create' } as unknown as LinearWebhookPayload;
    await expect(handle(payload, baseConfig)).rejects.toThrow("Unsupported action: create. Expected 'update'.");
  });

  it('throws on non-closed state', async () => {
    const payload = { ...SOURCE_EXAMPLE, data: { ...SOURCE_EXAMPLE.data, state: { name: 'Open' } } } as unknown as LinearWebhookPayload;
    await expect(handle(payload, baseConfig)).rejects.toThrow("Issue state 'Open' is not a closed state.");
  });

  it('throws when Linear GraphQL returns non-2xx', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Internal Server Error' }, 500));
    const config = { ...baseConfig, fetch };
    await expect(handle(SOURCE_EXAMPLE as unknown as LinearWebhookPayload, config)).rejects.toThrow(
      'Linear GraphQL request failed: 500 Internal Server Error at https://api.linear.app/graphql'
    );
    expect(calls.length).toBe(1);
    expect(calls[0].url).toBe('https://api.linear.app/graphql');
    expect(calls[0].json).toEqual({
      query: expect.any(String),
      variables: { issueId: '2174add1-f7c8-44e3-bbf3-2d60b5ea8bc9', after: null },
    });
  });

  it('throws when Discord returns non-2xx', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        return jsonResponse(TARGET_ENDPOINTS[0].response);
      }
      return jsonResponse({ error: 'Unauthorized' }, 401);
    });
    const config = { ...baseConfig, fetch };
    await expect(handle(SOURCE_EXAMPLE as unknown as LinearWebhookPayload, config)).rejects.toThrow(
      "Discord message post failed: 401 Unauthorized at https://discord.com/api/v10/channels/123456789/messages"
    );
    expect(calls.length).toBe(2);
    expect(calls[1].url).toBe('https://discord.com/api/v10/channels/123456789/messages');
  });

  it('happy path with exact request bodies and auth headers', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        expect(req.headers.get('authorization')).toBe('Bearer linear-key');
        return jsonResponse(TARGET_ENDPOINTS[0].response);
      }
      if (req.url === 'https://discord.com/api/v10/channels/123456789/messages') {
        expect(req.headers.get('authorization')).toBe('Bearer discord-token');
        expect(req.json).toEqual({
          content: "Digest: Linear issue 'Fix login bug' has 2 new comments:\\n\\n1. First comment\\n2. Second comment",
        });
        return jsonResponse(TARGET_ENDPOINTS[1].response);
      }
      throw new Error(`Unexpected request to ${req.url}`);
    });
    const config = { ...baseConfig, fetch };
    const result = await handle(SOURCE_EXAMPLE as unknown as LinearWebhookPayload, config);
    expect(result).toEqual({ discordMessageId: '123456789012345678', commentsFetched: 2 });
    expect(calls.length).toBe(2);
  });

  it('fetches multiple pages via cursor pagination', async () => {
    const firstPage = {
      data: {
        issue: {
          comments: {
            nodes: [{ id: 'c1', body: 'Comment 1', createdAt: '2020-01-23T12:55:00.000Z' }],
            pageInfo: { hasNextPage: true, endCursor: 'cursor-1' },
          },
        },
      },
    };
    const secondPage = {
      data: {
        issue: {
          comments: {
            nodes: [{ id: 'c2', body: 'Comment 2', createdAt: '2020-01-23T12:56:00.000Z' }],
            pageInfo: { hasNextPage: false, endCursor: null },
          },
        },
      },
    };
    let callCount = 0;
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url !== 'https://api.linear.app/graphql') throw new Error('Unexpected URL');
      callCount++;
      if (callCount === 1) {
        expect(req.json).toEqual({ query: expect.any(String), variables: { issueId: '2174add1-f7c8-44e3-bbf3-2d60b5ea8bc9', after: null } });
        return jsonResponse(firstPage);
      }
      if (callCount === 2) {
        expect(req.json).toEqual({ query: expect.any(String), variables: { issueId: '2174add1-f7c8-44e3-bbf3-2d60b5ea8bc9', after: 'cursor-1' } });
        return jsonResponse(secondPage);
      }
      throw new Error('Too many pagination calls');
    });
    const config = { ...baseConfig, fetch };
    const result = await handle(SOURCE_EXAMPLE as unknown as LinearWebhookPayload, config);
    expect(result.commentsFetched).toBe(2);
    expect(calls.length).toBe(3); // 2 GraphQL + 1 Discord
  });

  it('respects pagination safety cap', async () => {
    const pageWithNext = (cursor: string) => ({
      data: {
        issue: {
          comments: {
            nodes: [{ id: `c${cursor}`, body: `Comment ${cursor}`, createdAt: '2020-01-23T12:55:00.000Z' }],
            pageInfo: { hasNextPage: true, endCursor: `cursor-${Number(cursor)+1}` },
          },
        },
      },
    });
    let callCount = 0;
    const { fetch } = fakeFetch((req) => {
      if (req.url !== 'https://api.linear.app/graphql') throw new Error('Unexpected URL');
      callCount++;
      if (callCount <= 50) {
        return jsonResponse(pageWithNext(String(callCount)));
      }
      throw new Error('Should not exceed 50 pages');
    });
    const config = { ...baseConfig, fetch };
    await expect(handle(SOURCE_EXAMPLE as unknown as LinearWebhookPayload, config)).rejects.toThrow(
      'Pagination safety cap reached (50 pages)'
    );
  });
});

